it('draws crumbling ledges as stone tiles with deterministic warning cracks', () => {
  const ledge = {
    id: 'test-ledge', kind: 'crumbling-ledge' as const, x: 200, y: 120,
    width: 72, asset: 'stone', layer: 'world' as const,
  };
  const level = {
